import{z as l,x as A,o as n,c as b,q as r,j as E,D as i,d as e,s as o,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"OneBit / 1.58-bit 训练","description":"","frontmatter":{"title":"OneBit / 1.58-bit 训练","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/onebit-train.md","filePath":"llm/onebit-train.md","lastUpdated":1791413859000}'),m={name:"llm/onebit-train.md"};function p(d,a,h,T,g,u){const B=A("Mermaid");return n(),b("div",null,[a[2]||(a[2]=r('<h1 id="onebit-1-58-bit-训练" tabindex="-1">OneBit / 1.58-bit 训练 <a class="header-anchor" href="#onebit-1-58-bit-训练" aria-label="Permalink to &quot;OneBit / 1.58-bit 训练&quot;">​</a></h1><div class="epigraph"><p>把现成的全精度矩阵拆成符号加两个短向量，再在蒸馏里做量化感知训练，1-bit 权重建模才不必从随机初始化重跑一遍预训练；三元 1.58-bit 从零训则是另一条、更贵的配方。</p><footer>—— Xu 等，OneBit，NeurIPS 2024；对照 Ma 等 BitNet b1.58 的从零训练食谱</footer></div><p><a href="/llm/bitnet">BitNet</a> 证明：符号或三元权重可以从头训到可用。工程上更常见的起点却是已经花掉万卡时的 LLaMA / OPT 检查点。Yuzhuang Xu、Xu Han、Zhiyuan Liu、Wanxiang Che 等人的 <strong>OneBit</strong>（NeurIPS 2024，arXiv:2402.11295）走这条路：把每层 \\(W\\) 表示成 INT1 符号矩阵加两个 FP16 值向量，用符号–幅值分解（SVID）初始化，再量化感知蒸馏，目标是 <strong>W1A16</strong>。它不是 GPTQ 那种 one-shot 取整——1-bit 格子下 RTN 几乎只剩阈值，补偿也救不回来。本篇写「从预训练出发的 1-bit QAT」以及与 b1.58 从零训共享的 STE / 潜伏权重机制，不重复 BitLinear 的架构表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PTQ 在 4-bit 工作，到 2-bit 需要码本、旋转或可学习裁剪，见 <a href="/llm/omniquant">OmniQuant</a>、<a href="/llm/quip">QuIP</a>。到 <strong>1-bit</strong>，均匀量化的 \\(s,z\\) 失去意义：每个权重只是阈值两侧的两个电平，层输出 \\(WX\\) 的相对误差爆炸。图 1 一类曲线显示：GPTQ、LLM-QAT、OmniQuant 压到 2-bit 已明显掉点，再压到 1-bit 不可用。需要改表示，而不是再调一轮 Hessian。</p><p>从零训 BitNet 能避开「老师权重与学生格子不对齐」，但要重付预训练账单，且老师能力无法直接继承。OneBit 要的合同是：OPT / LLaMA / LLaMA-2 从 1.3B 到 13B，用远少于预训练的蒸馏步数，把能力迁到约 1-bit 权重上，零样本至少保住原文所说的 <strong>LLaMA 上非量化性能的 81%</strong> 量级，并让训练对学习率不那么脆。</p><h3 id="为什么-rtn-在-时失效" tabindex="-1">为什么 RTN 在 \\(N=1\\) 时失效 <a class="header-anchor" href="#为什么-rtn-在-时失效" aria-label="Permalink to &quot;为什么 RTN 在 $N=1$ 时失效&quot;">​</a></h3><p>\\(N=1\\) 时量化网格只有两个代表值。尺度与零点不再分配 bin，等价于一次硬阈值。权重矩阵的秩与浮点动态范围被一次性削掉，线性层作为 LLM 的核心算子先坏。BitNet 原文用 \\(\\mathrm{Sign}(W-\\mathrm{mean})\\) 加单一 absmean 尺度从零学；直接拿这套去量化已有 \\(W\\)，作者观察到既难收敛、精度也差。缺口在于：<strong>幅值结构</strong>被单一标量 \\(\\eta\\) 概括得太粗。</p><p><span class="marginnote">OneBit 的 1-bit 是权重；激活主实验是 16-bit。不要写成 W1A8 或与 b1.58 的 W1.58A8 混表。平均比特会因 \\(g,h\\) 两个向量略高于 1，4096×4096 层大约 1.007 bit 量级，不是营销上的「严格 1.000」。</span></p><p><span class="marginnote">数字实例：一层 \\(4096\\times4096\\) 的权重，FP16 是 \\(4096\\times4096\\times2\\) 字节 \\(=32\\) MB；打成 INT1 只有 2 MB，加上 \\(g,h\\) 两个向量（\\(4096\\times2\\times2\\) 字节 \\(=16\\) KB）后仍是 2 MB 出头——省下约 16 倍存储。decode 阶段每步都要把权重从显存搬进计算单元，这 16 倍直接变成带宽和时延的节省。</span></p><p><span class="marginnote">直觉类比：SVID 把权重矩阵拆成「哪些键被按下」和「每个键用多大力气」两件事——符号矩阵只记按不按（+1/−1），两个向量分别按行、按列补回力度。只丢力度表、保住指法，弹出来的曲子才不会面目全非。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>OneBit 的线性层在训练时写为</p> \\[W_{\\pm 1}=\\mathrm{Sign}(W),\\qquad Y=\\bigl[(X\\odot g)\\,W_{\\pm 1}^{\\top}\\bigr]\\odot h, \\]<p>推理时 \\(W_{\\pm 1}\\) 打成 INT1，\\(g,h\\) 仍 FP16。\\(g\\) 作用在输入通道，\\(h\\) 作用在输出通道，相当于把被削掉的浮点尺度做成两个 rank-1 方向，而不是 BitNet 的全局 \\(\\eta\\)。计算顺序写成先缩放 \\(X\\) 再乘符号矩阵，避免把 \\(W\\) 解回 FP16。</p><p>初始化用 <strong>SVID</strong>：\\(\\mathbf{W}\\approx \\mathbf{W}_{\\mathrm{sign}}\\odot(\\mathbf{a}\\mathbf{b}^{\\top})\\)，幅值矩阵做 rank-1（SVD 或 NMF）。命题上，带符号的 rank-1 比直接对 \\(W\\) 做 rank-1 的 Frobenius 误差更小，因为符号先保住了高秩模式。把 \\(\\mathbf{W}_{\\mathrm{sign}}\\to W_{\\pm 1}\\)、\\(b\\to g\\)、\\(a\\to h\\)，学生在蒸馏第 0 步就已经是老师的一个粗糙但同构的近似。</p><p>知识迁移：量化感知蒸馏，老师为原 FP16，学生带 STE 的 Sign。数据可以是原语料子集或老师生成文本（与 LLM-QAT 同族）。优化 \\(g,h\\) 与潜伏 \\(W\\)。主表覆盖 OPT、LLaMA、LLaMA-2 的 1.3B–13B，对照 WikiText 困惑度与零样本；1-bit OneBit 优于当时的 2-bit PTQ/QAT 基线，且随宽度增大更接近 FP16。</p>',17)),(n(),E(s,null,{default:i(()=>[o(B,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20FP%5B%22%E9%A2%84%E8%AE%AD%E7%BB%83%20FP16%20W%22%5D%20--%3E%20SVID%5B%22SVID%EF%BC%9A%E7%AC%A6%E5%8F%B7%20%E2%8A%97%20rank-1%20%E5%B9%85%E5%80%BC%22%5D%0A%20%20SVID%20--%3E%20STU%5B%22%E5%AD%A6%E7%94%9F%EF%BC%9AINT1%20%E7%AC%A6%E5%8F%B7%20%2B%20g%2Ch%22%5D%0A%20%20TCH%5B%22%E8%80%81%E5%B8%88%E5%89%8D%E5%90%91%22%5D%20--%3E%20KD%5B%22%E9%87%8F%E5%8C%96%E6%84%9F%E7%9F%A5%E8%92%B8%E9%A6%8F%22%5D%0A%20%20STU%20--%3E%20KD%0A%20%20KD%20--%3E%20STE%5B%22STE%20%E6%9B%B4%E6%96%B0%E6%BD%9C%E4%BC%8F%20W%20%E4%B8%8E%20g%2Ch%22%5D%0A%20%20STE%20--%3E%20INF%5B%22%E6%8E%A8%E7%90%86%EF%BC%9AW1A16%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h3",{id:"_1-58-bit-从零训-同一套-ste-另一张账单",tabindex:"-1"},[e("1.58-bit 从零训：同一套 STE，另一张账单 "),t("a",{class:"header-anchor",href:"#_1-58-bit-从零训-同一套-ste-另一张账单","aria-label":'Permalink to "1.58-bit 从零训：同一套 STE，另一张账单"'},"​")],-1)),a[4]||(a[4]=t("p",null,"b1.58 不从老师出发。潜伏 \\(W\\) 用 Adam 更新，前向 absmean 三元量化，激活 8-bit，骨干 LLaMA-alike，数据与 token 数必须与 FP16 对照对齐（原文 100B RedPajama，另有 2T 配方）。工程清单与 OneBit 部分重叠：混合精度优化器、STE clip、SubLN/RMSNorm 稳住激活、低比特核只在推理启用。差别是目标函数——语言建模似然 vs 蒸馏对齐——以及权重格子 \\(\\{+1,-1\\}\\) 加双向量 vs \\(\\{-1,0,1\\}\\) 加单一 \\(\\gamma\\)。把「1.58-bit 训练」理解成「把 GPTQ 再跑到 1.58」是错的；没有从零或长程 QAT，三元格子站不住。",-1)),a[5]||(a[5]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=t("p",null,"SVID 把「方向」和「尺度」拆开。符号矩阵容量大、占空间小，负责保持几乎满秩的连接模式；两个向量用 \\(O(n+m)\\) 的 FP16 去拟合每行每列的典型幅度。前向 \\(Y\\approx[(X\\odot b)W_{\\mathrm{sign}}^{\\top}]\\odot a\\) 与 \\(XW^{\\top}\\) 同构，所以蒸馏初期 logits 不会从随机噪声开始。STE 对 Sign 的梯度是直通，真正能学的是潜伏 \\(W\\) 如何把质量推过 0，以及 \\(g,h\\) 如何吸收剩余尺度。学习率过大时，Sign 频繁翻转，等于每步换拓扑；SVID 把起点放到老师附近，翻转率下降，这是原文强调「对超参更稳」的机制来源。",-1)),a[7]||(a[7]=t("p",null,"与 BitNet 单一 \\(\\eta\\) 相比，双向量允许不同输出通道有不同增益，更接近逐通道量化的自由度，却几乎不加平均比特。与 LLM-QAT 的可学习量化参数相比，OneBit 把自由度做成结构化的符号加 rank-1，而不是在均匀网格上再学一组 \\(s\\)。",-1)),(n(),E(s,null,{default:i(()=>[o(B,{id:"mermaid-63",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20OB%5B%22OneBit%EF%BC%9A%E7%BB%A7%E6%89%BF%E5%B7%B2%E6%9C%89%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%0A%20%20%20%20O1%5B%22%E8%B5%B7%E7%82%B9%EF%BC%9AFP16%20%E9%A2%84%E8%AE%AD%E7%BB%83%E6%9D%83%E9%87%8D%22%5D%20--%3E%20O2%5B%22Sign%20%2B%20g%2Ch%20%E5%8F%8C%E5%90%91%E9%87%8F%22%5D%0A%20%20%20%20O2%20--%3E%20O3%5B%22%E8%92%B8%E9%A6%8F%20QAT%EF%BC%9A%E7%9B%AE%E6%A0%87%20W1A16%22%5D%0A%20%20%20%20O3%20--%3E%20O4%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E8%92%B8%E9%A6%8F%E6%AD%A5%E6%95%B0%EF%BC%8C%E8%83%BD%E5%8A%9B%E6%9D%A5%E8%87%AA%E8%80%81%E5%B8%88%22%5D%0A%20%20end%0A%20%20subgraph%20BN%5B%22BitNet%20b1.58%EF%BC%9A%E4%BB%8E%E9%9B%B6%E8%AE%AD%E7%BB%83%22%5D%0A%20%20%20%20B1%5B%22%E8%B5%B7%E7%82%B9%EF%BC%9A%E9%9A%8F%E6%9C%BA%E5%88%9D%E5%A7%8B%E5%8C%96%22%5D%20--%3E%20B2%5B%22%E4%B8%89%E5%85%83%20%E2%88%921%20%2F%200%20%2F%20%2B1%20%E5%8A%A0%E5%8D%95%E4%B8%80%20%CE%B3%22%5D%0A%20%20%20%20B2%20--%3E%20B3%5B%22%E8%AF%AD%E8%A8%80%E5%BB%BA%E6%A8%A1%E6%8D%9F%E5%A4%B1%E4%BB%8E%E5%A4%B4%E5%AD%A6%22%5D%0A%20%20%20%20B3%20--%3E%20B4%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E5%AE%8C%E6%95%B4%E9%A2%84%E8%AE%AD%E7%BB%83%E8%B4%A6%E5%8D%95%22%5D%0A%20%20end%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r('<p><span class="marginnote">这张图回答的问题是：两条低比特路线到底差在哪一步。常见误区是把「1.58-bit 训练」理解成「拿 GPTQ 再压到 1.58」——三元格子没有从零训练或长程 QAT 根本站不住；反过来，已经花大钱训好的检查点，也没有必要重付一遍预训练账单。</span></p><p><span class="marginnote">蒸馏对齐的是老师的条件分布，不是用户任务。老师若已有幻觉或安全拒答，学生会学走。评测应报相对老师的保持率，并写明 WikiText / 零样本套件，不要把 81% 写成所有基准的下限。</span></p><h3 id="训练显存并不等于推理-1-bit" tabindex="-1">训练显存并不等于推理 1-bit <a class="header-anchor" href="#训练显存并不等于推理-1-bit" aria-label="Permalink to &quot;训练显存并不等于推理 1-bit&quot;">​</a></h3><p>QAT 前向可以假量化，反向与 Adam 仍是全精度潜伏张量。13B 级蒸馏需要的 GPU 小时远小于预训练，但仍是 PTQ 的几十到几百倍。若只能接受校准级预算，应回到 3–4 bit 的 <a href="/llm/gptq">GPTQ</a> / <a href="/llm/spqr">SpQR</a>，而不是强行 1-bit。推理核要能把 INT1 与两个向量融合；先解包成 FP16 再 gemm，只省存储、不省算。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>OneBit 不提供与 b1.58 同场的「同 token 从零训到匹配 FP16」。它压缩已有模型，能力上限受老师与蒸馏数据约束。W1A16 在 decode 上省权重带宽；prefill 大 batch 仍可能是计算墙，且激活仍 16-bit。lm_head、嵌入是否 1-bit 按实现；原文聚焦 Linear。与 BitNet 选型：没有预训练预算、要新架构新核，走 b1.58；有强检查点、接受蒸馏与约 81% 保持，走 OneBit。不要把微软后续 2B4T 开源权重的评测表写进 2024 年清华大学 / 哈工大这篇 NeurIPS。</p><p><span class="marginnote">出处：Xu, Han, Yang, Wang, Zhu, Liu, Liu, Che，<em>OneBit: Towards Extremely Low-bit Large Language Models</em>，NeurIPS 2024，arXiv:2402.11295。从零三元食谱见 Ma et al.，arXiv:2402.17764。PTQ 对照见 GPTQ / OmniQuant。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>1-bit PTQ 的 RTN 退化为阈值，必须改表示或从零训。</li><li>OneBit：符号矩阵 + 双 FP16 向量，SVID 初始化，QAT 蒸馏，W1A16。</li><li>b1.58 从零训共享 STE 与潜伏权重，但不继承老师，账单是完整预训练。</li><li>训练时优化器仍是高精度；推理红利取决于 INT1 核。</li><li>出处：Xu et al.，NeurIPS 2024；对照 Wang/Ma BitNet 系列。</li></ul>',9))])}const F=l(m,[["render",p]]);export{P as __pageData,F as default};
